// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address fuzzedCaller) public {
        vm.assume(fuzzedCaller != address(this));

        address originalOwner = c.owner();
        address newOwner = address(0x1234);

        bool success;
        vm.prank(fuzzedCaller);
        try c.setOwner(newOwner) returns (bool ret) {
            success = true;
        } catch {
            success = false;
        }

        assertTrue(!success || c.owner() == originalOwner);
    }
}
